import Foundation
import Intents
import UserNotifications

/*
 * SINGLE SOURCE OF TRUTH for the notification content mutation.
 *
 * This file is compiled into TWO targets:
 *   1. the ExpoNotifPrefs pod (used by `simulateNsePush`, in the app process)
 *   2. the DemoNSE extension (copied into ios/DemoNSE/ by
 *      plugins/notificationsExtension/withExtensionSourceFiles.js)
 *
 * so the two cannot diverge. Edit it HERE only; the copy under ios/ is
 * regenerated by `expo prebuild`. It must not import ExpoModulesCore or
 * reference APP_GROUP: callers pass in the UserDefaults handle.
 */
enum NSEMutation {
  /// One serial queue per process for keys the NSE itself read-modify-writes.
  static let prefsQueue = DispatchQueue(label: "NSEPrefsQueue")

  /*
   * Applies the synchronous mutations for `reason`. Returns the new badge count
   * if the badge was touched, otherwise nil.
   *
   * Chat notifications deliberately do not touch the badge - they are counted
   * by the conversation list, not the notifications tab.
   */
  @discardableResult
  static func mutate(
    _ content: UNMutableNotificationContent,
    reason: String,
    userInfo: [AnyHashable: Any],
    prefs: UserDefaults?
  ) -> Int? {
    if reason == "chat-message" {
      // Read-only preference (written only by the app): no queue needed.
      if prefs?.bool(forKey: "playSoundChat") == true {
        content.sound = UNNotificationSound(
          named: UNNotificationSoundName(rawValue: "dm.aiff")
        )
      } else {
        content.sound = nil
      }
      // For group convos surface the group name as the subtitle; the title is
      // taken over by INSendMessageIntent to show the sender.
      if userInfo["convoKind"] as? String == "group",
        let groupName = userInfo["groupName"] as? String,
        !groupName.isEmpty {
        content.subtitle = groupName
      }
      return nil
    }

    // Read-modify-write across processes is not atomic; the serial queue
    // serializes concurrent pushes within this process.
    var result = 0
    prefsQueue.sync {
      var count = prefs?.integer(forKey: "badgeCount") ?? 0
      count += 1
      content.badge = NSNumber(value: count)
      prefs?.setValue(count, forKey: "badgeCount")
      result = count
    }
    return result
  }

  /*
   * Full pipeline after `mutate`: for chat messages, fetches the avatar (if
   * any) WITHOUT blocking a thread and then builds the Communication
   * Notification. `completion` is called exactly once unless the returned
   * handle is cancelled first (then never).
   */
  @discardableResult
  static func finalize(
    _ content: UNMutableNotificationContent,
    reason: String,
    userInfo: [AnyHashable: Any],
    completion: @escaping (UNNotificationContent) -> Void
  ) -> AvatarDownload? {
    guard reason == "chat-message" else {
      completion(content)
      return nil
    }
    guard let urlString = userInfo["senderAvatarUrl"] as? String else {
      completion(communicationContent(from: content, userInfo: userInfo, avatar: nil))
      return nil
    }
    return AvatarDownload.start(urlString: urlString) { image in
      completion(communicationContent(from: content, userInfo: userInfo, avatar: image))
    }
  }

  /*
   * Turns a plain notification into an iOS Communication Notification: sender
   * name, avatar, Focus-mode filtering, Siri suggestions. Cannot be expressed
   * in the push payload; requires building and donating an INSendMessageIntent.
   */
  static func communicationContent(
    from content: UNMutableNotificationContent,
    userInfo: [AnyHashable: Any],
    avatar: INImage?
  ) -> UNNotificationContent {
    let senderDisplayName = userInfo["senderDisplayName"] as? String ?? "Unknown"
    let isGroup = userInfo["convoKind"] as? String == "group"

    let sender = INPerson(
      personHandle: INPersonHandle(value: userInfo["senderHandle"] as? String, type: .unknown),
      nameComponents: nil,
      displayName: senderDisplayName,
      image: avatar,
      contactIdentifier: nil,
      customIdentifier: nil
    )

    var speakableGroupName: INSpeakableString?
    if isGroup, let groupName = userInfo["groupName"] as? String, !groupName.isEmpty {
      speakableGroupName = INSpeakableString(spokenPhrase: groupName)
    }

    let intent = INSendMessageIntent(
      recipients: nil,
      outgoingMessageType: .outgoingMessageText,
      content: content.body,
      speakableGroupName: speakableGroupName,
      conversationIdentifier: userInfo["convoId"] as? String,
      serviceName: nil,
      sender: sender,
      attachments: nil
    )

    /*
     * The payload omits the full recipient list for group convos. With no
     * signal of multiple recipients iOS classifies the notification as
     * `MessagingDirect` and ignores `speakableGroupName`. `recipientCount` on
     * the donation metadata is Apple's documented escape hatch.
     */
    if isGroup, let memberCount = userInfo["groupMemberCount"] as? Int, memberCount > 0 {
      let metadata = INSendMessageIntentDonationMetadata()
      metadata.recipientCount = memberCount
      intent.donationMetadata = metadata
    }
    if isGroup, let avatar {
      intent.setImage(avatar, forParameterNamed: \.speakableGroupName)
    }

    let interaction = INInteraction(intent: intent, response: nil)
    interaction.direction = .incoming
    interaction.donate(completion: nil)

    do {
      return try content.updating(from: intent)
    } catch {
      // Throws when the communication entitlement is not honored (common on a
      // simulator build with no signing team). Degrade, don't drop.
      return content
    }
  }
}

/*
 * Bounded, non-blocking avatar download.
 *
 * - https only, no credentials in the URL, port 443 only, and a public-looking
 *   host (no IP literals, localhost, or local-network suffixes). Redirects are
 *   re-validated.
 * - Response is capped at `maxBytes`: rejected early from Content-Length, and
 *   cancelled mid-stream if the body exceeds it anyway.
 * - `overallTimeout` is a hard wall-clock deadline for the WHOLE download, not
 *   an idle timer (URLRequest.timeoutInterval resets on every received byte,
 *   so a slow-drip server could hold it forever).
 * - Callback style: no thread is parked on a semaphore.
 */
final class AvatarDownload: NSObject, URLSessionDataDelegate {
  static let maxBytes = 2 * 1024 * 1024
  static let idleTimeout: TimeInterval = 5
  static let overallTimeout: TimeInterval = 8

  private let lock = NSLock()
  private var buffer = Data()
  private var completion: ((INImage?) -> Void)?
  private var session: URLSession?

  static func isAcceptable(_ url: URL) -> Bool {
    guard url.scheme?.lowercased() == "https",
      url.user == nil, url.password == nil,
      url.port == nil || url.port == 443,
      let host = url.host?.lowercased(), !host.isEmpty
    else { return false }
    if host.contains(":") || host.hasPrefix("[") { return false }  // IPv6 literal
    if host.allSatisfy({ $0.isNumber || $0 == "." }) { return false }  // IPv4 literal
    if !host.contains(".") { return false }
    for suffix in [".local", ".localdomain", ".internal", ".lan", ".home", ".localhost"] {
      if host.hasSuffix(suffix) { return false }
    }
    return host != "localhost"
  }

  /// Calls `completion(nil)` synchronously for an unacceptable URL.
  static func start(urlString: String, completion: @escaping (INImage?) -> Void) -> AvatarDownload? {
    guard let url = URL(string: urlString), isAcceptable(url) else {
      completion(nil)
      return nil
    }
    let download = AvatarDownload()
    download.completion = completion

    let config = URLSessionConfiguration.ephemeral
    config.timeoutIntervalForRequest = idleTimeout
    config.timeoutIntervalForResource = overallTimeout  // overall cap, enforced by URLSession
    config.waitsForConnectivity = false
    let session = URLSession(configuration: config, delegate: download, delegateQueue: nil)
    let task = session.dataTask(with: URLRequest(url: url))
    download.session = session
    task.resume()

    // Belt and braces: our own wall-clock deadline in case the config one is
    // not honored for some stall.
    DispatchQueue.global().asyncAfter(deadline: .now() + overallTimeout) { [weak download] in
      download?.finish(nil)
    }
    return download
  }

  /// Abandons the download without calling the completion.
  func cancel() {
    lock.lock()
    completion = nil
    let session = self.session
    self.session = nil
    lock.unlock()
    session?.invalidateAndCancel()
  }

  private func finish(_ data: Data?) {
    lock.lock()
    let completion = self.completion
    self.completion = nil
    let session = self.session
    self.session = nil
    lock.unlock()
    session?.invalidateAndCancel()  // also releases the delegate cycle
    guard let completion else { return }
    completion(data.flatMap { INImage(imageData: $0) })
  }

  func urlSession(
    _ session: URLSession, dataTask: URLSessionDataTask,
    didReceive response: URLResponse,
    completionHandler: @escaping (URLSession.ResponseDisposition) -> Void
  ) {
    guard let http = response as? HTTPURLResponse, http.statusCode == 200,
      response.expectedContentLength <= Int64(Self.maxBytes),
      response.mimeType?.hasPrefix("image/") == true
    else {
      completionHandler(.cancel)
      finish(nil)
      return
    }
    completionHandler(.allow)
  }

  func urlSession(_ session: URLSession, dataTask: URLSessionDataTask, didReceive data: Data) {
    lock.lock()
    buffer.append(data)
    let tooBig = buffer.count > Self.maxBytes
    lock.unlock()
    if tooBig {
      dataTask.cancel()
      finish(nil)
    }
  }

  func urlSession(
    _ session: URLSession, task: URLSessionTask,
    willPerformHTTPRedirection response: HTTPURLResponse,
    newRequest request: URLRequest,
    completionHandler: @escaping (URLRequest?) -> Void
  ) {
    if let url = request.url, Self.isAcceptable(url) {
      completionHandler(request)
    } else {
      completionHandler(nil)  // stop: the 3xx body fails the status check
    }
  }

  func urlSession(_ session: URLSession, task: URLSessionTask, didCompleteWithError error: Error?) {
    lock.lock()
    let data = buffer
    lock.unlock()
    finish(error == nil ? data : nil)
  }
}
